Object.assign(en, {"rxn.fva": "Flux range (FVA)", "rxn.fvaTitle": "Minimum and maximum flux of this reaction among all solutions that reach the same objective value", "rxn.fvaBusy": "Computing the flux range…", "rxn.fvaSteady": "The flux range is computed in steady-state mode.", "rxn.fvaRange": "Flux range at the optimal objective: {lo} … {hi} mmol/gDW/h", "rxn.fvaFixed": "Fixed: every optimal solution needs exactly this flux.", "rxn.fvaZero": "Always zero: no optimal solution uses this reaction.", "rxn.fvaRequired": "Required: every optimal solution uses it, but the amount can vary.", "rxn.fvaFree": "Optional: optimal solutions exist with and without it; the flux shown is the one pFBA chose."});
Object.assign(es, {"rxn.fva": "Rango de flujo (FVA)", "rxn.fvaTitle": "Flujo mínimo y máximo de esta reacción entre todas las soluciones que alcanzan el mismo valor del objetivo", "rxn.fvaBusy": "Calculando el rango de flujo…", "rxn.fvaSteady": "El rango de flujo se calcula en modo estacionario.", "rxn.fvaRange": "Rango de flujo con el objetivo óptimo: {lo} … {hi} mmol/gDW/h", "rxn.fvaFixed": "Fijo: toda solución óptima necesita exactamente este flujo.", "rxn.fvaZero": "Siempre cero: ninguna solución óptima usa esta reacción.", "rxn.fvaRequired": "Necesaria: toda solución óptima la usa, pero la cantidad puede variar.", "rxn.fvaFree": "Opcional: hay soluciones óptimas con y sin ella; el flujo mostrado es el que eligió el pFBA."});
