Object.assign(en, {"scr.button": "Screen essential genes", "scr.title": "Knock out, one by one, every detected gene whose reactions carry flux, and see which ones lower the objective (cell type, medium and measured fluxes included). With knockouts in the list, the screen runs on top of them and marks the synthetic lethal genes", "scr.stop": "Stop the screen", "scr.needSteady": "The screen needs an optimal steady-state result: simulate first.", "scr.progress": "Screening {genes} genes: {done} of {total} linear programs…", "scr.summary": "{n} genes screened in {ctx} ({lp} linear programs, {s} s): {ess} essential, {red} lower the objective.", "scr.stopped": "Stopped before the end.", "scr.ess": "Essential (objective below 1 %)", "scr.red": "Lower the objective (1–95 %)", "scr.addTitle": "Add this knockout", "scr.relaxedNote": "* the measured fluxes had to be relaxed for this knockout."});
Object.assign(es, {"scr.button": "Cribar genes esenciales", "scr.title": "Anula uno a uno cada gen detectado cuyas reacciones llevan flujo y muestra cuáles bajan el objetivo (con tipo celular, medio y flujos medidos). Si hay knockouts en la lista, el cribado se hace encima de ellos y marca los genes letales sintéticos", "scr.stop": "Detener el cribado", "scr.needSteady": "El cribado necesita un resultado estacionario óptimo: simula primero.", "scr.progress": "Cribando {genes} genes: {done} de {total} programas lineales…", "scr.summary": "{n} genes cribados en {ctx} ({lp} programas lineales, {s} s): {ess} esenciales, {red} bajan el objetivo.", "scr.stopped": "Detenido antes del final.", "scr.ess": "Esenciales (objetivo por debajo del 1 %)", "scr.red": "Bajan el objetivo (1–95 %)", "scr.addTitle": "Añadir este knockout", "scr.relaxedNote": "* hubo que relajar los flujos medidos para este knockout."});
