Object.assign(es, {"scr.nRxns": "{n} reacciones", "scr.rescuedTitle": "No detectado en este tipo celular; vuelto a encender por la tarea «{task}»", "scr.rescuedNote": "↺ gen no detectado en el tipo celular y vuelto a encender porque una tarea metabólica lo necesita: su esencialidad viene de esa tarea, no de datos de la célula.", "scr.none": "Cribados sin efecto sobre el objetivo ({n})"});
Object.assign(en, {"obj.name.biomassGeneric": "Growth (generic cell biomass, MAR13082)", "obj.note.biomassGeneric": "Maximises MAR13082, the generic cell biomass reaction that Mouse-GEM inherits from Human-GEM: the same composition per gram of dry weight (protein, lipid, DNA, RNA, glycogen, metabolite and cofactor pools, 45 ATP per gDW). Mouse-GEM's own objective (MAR00021) takes one unit of each of 33 precursors, so its value is not a growth rate (about 0.00016). MAR13082 is closed in the published model and is opened only while it is the objective. Growth in h⁻¹, comparable with Human-GEM; the composition is that of a generic human cell."});
Object.assign(es, {"obj.name.biomassGeneric": "Crecimiento (biomasa celular genérica, MAR13082)", "obj.note.biomassGeneric": "Maximiza MAR13082, la reacción de biomasa celular genérica que Mouse-GEM hereda de Human-GEM: la misma composición por gramo de peso seco (reservas de proteína, lípidos, ADN, ARN, glucógeno, metabolitos y cofactores, 45 ATP por gDW). El objetivo propio de Mouse-GEM (MAR00021) toma una unidad de cada uno de 33 precursores, así que su valor no es una tasa de crecimiento (unos 0,00016). MAR13082 está cerrada en el modelo publicado y sólo se abre mientras es el objetivo. Crecimiento en h⁻¹, comparable con Human-GEM; la composición es la de una célula humana genérica."});
Object.assign(en, {"ctt.summary": "What {ctx} switches off: {off} genes, {rx} reactions", "ctt.rxns": "Reactions ({n})", "ctt.genes": "Genes ({n})", "ctt.filter": "Filter by name, gene, ID or pathway…", "ctt.csv": "CSV", "ctt.th.rxn": "Reaction", "ctt.th.id": "ID", "ctt.th.path": "Pathway", "ctt.th.offGenes": "Genes not detected", "ctt.th.gene": "Gene", "ctt.th.gname": "Name", "ctt.th.nrx": "Reactions blocked", "ctt.th.paths": "Pathways", "ctt.showing": "Showing {n} of {total}; click a column to sort", "ctt.note": "Genes with 0 reactions blocked are covered by a detected isoenzyme. Transports of freely diffusing molecules are never blocked.", "ctt.loading": "Loading the model…", "cat.expand": "Show the genes and reactions it switches off"});
