Object.assign(en, {"h.tour": "Walkthrough", "h.tourTitle": "A step-by-step tour of the interface", "tour.next": "Next", "tour.back": "Back", "tour.close": "Close", "tour.finish": "Done", "tour.welcome.t": "Welcome to MetfluxLive", "tour.welcome.b": "MetfluxLive computes where metabolic flux goes in a genome-scale model (flux balance analysis) and follows isotope labels through it. This tour shows what each part of the screen is for. Use → / ← or the buttons; Esc closes it.", "tour.model.t": "Model", "tour.model.b": "The organism: human, mouse, rat, zebrafish, fruit fly or C. elegans. Each model keeps its own medium, edits and settings.", "tour.search.t": "Search", "tour.search.b": "Find a metabolite, reaction, gene or pathway (Ctrl+K). Picking a result opens it on the map and in the right panel.", "tour.mode.t": "Steady state or Dynamic", "tour.mode.b": "Steady state solves one FBA. Dynamic follows the culture over time: the medium is consumed, biomass grows and labels spread step by step.", "tour.run.t": "Simulate and Auto", "tour.run.b": "Simulate solves the model with everything in the left panel. With Auto on, it re-runs by itself after each change; a dot on Simulate means the result is out of date.", "tour.context.t": "Cell type", "tour.context.b": "Choose a cell line, cell type or tissue: genes not detected there are switched off, and reactions left without an enzyme are blocked. The catalogue lists them all.", "tour.medium.t": "Medium and sources", "tour.medium.b": "What the cell can take up and at what concentration. ⚛ next to a metabolite labels its atoms (13C, 15N) to trace them.", "tour.measured.t": "Measured exchange fluxes", "tour.measured.b": "Pins uptake and secretion to rates measured in real cells (NCI-60, HEK293, fibroblasts, liver), so the internal fluxes become realistic.", "tour.objective.t": "Cellular objective", "tour.objective.b": "What the cell is assumed to maximise: growth, ATP, or a cell function such as making urea or glucose. pFBA picks the solution with the least total flux.", "tour.perturb.t": "Knockout / knockdown", "tour.perturb.b": "Switch off or reduce a gene or reaction and compare with the unperturbed cell. The screen finds the essential genes of the current cell type.", "tour.compare.t": "Compare", "tour.compare.b": "Save the current situation as a scenario, change something, and see the differences on the map and in the panels.", "tour.map.t": "Map", "tour.map.b": "Line width and particle speed show flux. Double-click a group to open its pathway; click a node for its details. Grey dashed lines are reactions blocked by the cell type.", "tour.view.t": "Map layout and filter", "tour.view.b": "Arrange the map by cascade (steps from the medium), by pathway or by compartment, and show everything or only what a tracer or a perturbation affects.", "tour.lines.t": "What the lines carry", "tour.lines.b": "Between pathways, lines can show carbon or nitrogen atoms, NADH, NADPH, ATP-like cofactors or Gibbs energy.", "tour.details.t": "Summary and details", "tour.details.b": "Growth, uptake and secretion, what limits the objective and where the label goes; for a reaction, its flux, flux range (FVA) and genes.", "tour.edit.t": "Edit model", "tour.edit.b": "Add or remove reactions, enzymes and metabolites. Edits are validated and kept as a list you can export.", "tour.files.t": "Import and Download", "tour.files.b": "Download fluxes, labelling, charts and the whole session as files; import a session to repeat the calculations elsewhere.", "tour.docs.t": "Documentation", "tour.docs.b": "How everything is computed, where every number comes from, worked examples and limitations.", "tour.end.t": "That's it", "tour.end.b": "A good first experiment: label glucose with ⚛ in the medium and follow the label on the map. You can restart this tour any time from Walkthrough."});
Object.assign(es, {"h.tour": "Recorrido", "h.tourTitle": "Un recorrido paso a paso por la interfaz", "tour.next": "Siguiente", "tour.back": "Atrás", "tour.close": "Cerrar", "tour.finish": "Hecho", "tour.welcome.t": "Bienvenido a MetfluxLive", "tour.welcome.b": "MetfluxLive calcula por dónde va el flujo metabólico en un modelo a escala genómica (análisis de balance de flujos) y sigue marcas isotópicas a través de él. Este recorrido muestra para qué sirve cada parte de la pantalla. Usa → / ← o los botones; Esc lo cierra.", "tour.model.t": "Modelo", "tour.model.b": "El organismo: humano, ratón, rata, pez cebra, mosca de la fruta o C. elegans. Cada modelo guarda su propio medio, ediciones y ajustes.", "tour.search.t": "Búsqueda", "tour.search.b": "Busca un metabolito, reacción, gen o ruta (Ctrl+K). Al elegir un resultado se abre en el mapa y en el panel derecho.", "tour.mode.t": "Estacionario o Dinámico", "tour.mode.b": "Estacionario resuelve un FBA. Dinámico sigue el cultivo en el tiempo: el medio se consume, la biomasa crece y las marcas se extienden paso a paso.", "tour.run.t": "Simular y Auto", "tour.run.b": "Simular resuelve el modelo con todo lo del panel izquierdo. Con Auto activado, se repite solo tras cada cambio; un punto en Simular indica que el resultado está desactualizado.", "tour.context.t": "Tipo celular", "tour.context.b": "Elige una línea celular, un tipo celular o un tejido: los genes que no se detectan en él se apagan y se bloquean las reacciones que se quedan sin enzima. El catálogo los lista todos.", "tour.medium.t": "Medio y fuentes", "tour.medium.b": "Lo que la célula puede captar y a qué concentración. ⚛ junto a un metabolito marca sus átomos (13C, 15N) para seguirlos.", "tour.measured.t": "Flujos de intercambio medidos", "tour.measured.b": "Fija la captación y la excreción a tasas medidas en células reales (NCI-60, HEK293, fibroblastos, hígado), para que los flujos internos sean realistas.", "tour.objective.t": "Objetivo celular", "tour.objective.b": "Lo que se supone que la célula maximiza: crecimiento, ATP o una función celular como producir urea o glucosa. El pFBA elige la solución con menos flujo total.", "tour.perturb.t": "Knockout / knockdown", "tour.perturb.b": "Apaga o reduce un gen o una reacción y compara con la célula sin perturbar. El cribado encuentra los genes esenciales del tipo celular actual.", "tour.compare.t": "Comparar", "tour.compare.b": "Guarda la situación actual como escenario, cambia algo y mira las diferencias en el mapa y en los paneles.", "tour.map.t": "Mapa", "tour.map.b": "El grosor de las líneas y la velocidad de las partículas muestran el flujo. Doble clic en un grupo abre su ruta; clic en un nodo muestra sus detalles. Las líneas grises discontinuas son reacciones bloqueadas por el tipo celular.", "tour.view.t": "Disposición y filtro del mapa", "tour.view.b": "Ordena el mapa en cascada (pasos desde el medio), por ruta o por compartimento, y muestra todo o sólo lo que afecta un trazador o una perturbación.", "tour.lines.t": "Qué llevan las líneas", "tour.lines.b": "Entre rutas, las líneas pueden mostrar átomos de carbono o nitrógeno, NADH, NADPH, cofactores tipo ATP o energía de Gibbs.", "tour.details.t": "Resumen y detalles", "tour.details.b": "Crecimiento, captación y excreción, qué limita el objetivo y adónde va la marca; para una reacción, su flujo, su rango de flujo (FVA) y sus genes.", "tour.edit.t": "Editar modelo", "tour.edit.b": "Añade o quita reacciones, enzimas y metabolitos. Las ediciones se validan y se guardan como una lista que se puede exportar.", "tour.files.t": "Importar y Descargar", "tour.files.b": "Descarga flujos, marcaje, gráficos y la sesión completa como archivos; importa una sesión para repetir los cálculos en otro sitio.", "tour.docs.t": "Documentación", "tour.docs.b": "Cómo se calcula todo, de dónde sale cada número, ejemplos resueltos y limitaciones.", "tour.end.t": "Eso es todo", "tour.end.b": "Un buen primer experimento: marca la glucosa con ⚛ en el medio y sigue la marca en el mapa. Puedes repetir este recorrido cuando quieras desde Recorrido."});
Object.assign(en, {"ctx.group.user": "Your data", "ctx.badge.user": "Yours", "ctx.src.user": "your RNA-seq", "rna.open": "＋ Use your own RNA-seq data…", "rna.openTitle": "Build a cell type from your own gene expression table", "rna.title": "Cell type from your RNA-seq data", "rna.howH": "What data are needed (read first)", "rna.how": "<p>A text table (<b>.tsv</b>, <b>.csv</b> or <b>.txt</b>) with <b>one row per gene</b>:</p><ul><li><b>One column of gene identifiers.</b> Human-GEM: Ensembl gene IDs (<code>ENSG00000111640</code>, a version suffix like <code>.15</code> is fine) or HGNC symbols (<code>GAPDH</code>). Mouse-GEM / Rat-GEM: MGI / RGD symbols (<code>Gapdh</code>). Zebrafish-GEM: ZFIN symbols (<code>gapdh</code>); Fruitfly-GEM: FlyBase symbols (<code>Gapdh1</code>); Worm-GEM: WormBase gene names (<code>gpd-1</code>). The column is detected automatically.</li><li><b>One or more columns of normalised expression</b> on a linear scale: <b>TPM</b> (best), FPKM/RPKM, or CPM for single-cell data pooled per cell type. <b>Not raw read counts</b>: they depend on gene length and sequencing depth. If your values are log2(x+1), tick the box and they are converted back.</li><li><b>Gene level</b>, not transcript level: sum the transcripts of each gene first.</li><li>Replicates: choose one column or the mean of all numeric columns. A header row and comment lines starting with # are allowed.</li></ul><pre>gene_id\tTPM_rep1\tTPM_rep2\nENSG00000111640\t2410.5\t2388.1\nENSG00000134333\t396.7\t402.0\nENSG00000156515\t49.8\t51.2</pre><p><b>What happens.</b> Genes below the cut-off (default <b>1</b>, the Human Protein Atlas convention for TPM) are switched off; genes not in your table stay on. Reactions left without an enzyme are blocked, and genes are switched back on until the 57 essential metabolic tasks of Human-GEM are possible again, exactly as for the catalogue (Docs › Cell types). This runs in your browser and takes a few minutes (up to about seven on a busy computer); you can keep working meanwhile. <b>Your data never leave this computer</b>: the result is saved in this browser and inside the sessions you export.</p><p><b>Choosing the cut-off.</b> 1 TPM suits most bulk RNA-seq. With shallow sequencing or 3′ protocols many real genes fall below 1: lower it (0.5). A higher cut-off switches off more genes and leans more on the task rescue.</p>", "rna.file": "Expression table:", "rna.idCol": "Gene identifiers", "rna.valCol": "Expression values", "rna.thr": "Cut-off (genes below are off)", "rna.name": "Name of this cell type", "rna.log": "Values are log2(x+1): convert them back to a linear scale", "rna.column": "column {n}", "rna.meanCols": "mean of the {n} numeric columns", "rna.preview": "{rows} rows read, {used} matched to {matched} of the {n} model genes ({pct} %). With the cut-off {thr}, {off} genes would be switched off before the task rescue.", "rna.lowMatch": "Fewer than half of the model genes were found: check the identifier column and the model (human IDs for Human-GEM, mouse symbols for Mouse-GEM). Genes missing from the table stay on.", "rna.build": "Build cell type", "rna.loading": "Starting the solver…", "rna.progress": "Checking metabolic task {i} of {n}… ({s} s)", "rna.errEmpty": "The file has no data rows.", "rna.errNoValues": "No column of numbers was found besides the gene identifiers.", "rna.chipInfo": "From {file}: {matched} of {total} genes in the table, cut-off {thr}.", "rna.delete": "delete", "rna.deleteConfirm": "Delete the cell type «{name}» from this browser?", "rna.storageFull": "The browser storage is full: the cell type is used now but not kept."});
Object.assign(es, {"ctx.group.user": "Tus datos", "ctx.badge.user": "Tuyo", "ctx.src.user": "tu RNA-seq", "rna.open": "＋ Usar tus propios datos de RNA-seq…", "rna.openTitle": "Construir un tipo celular a partir de tu propia tabla de expresión génica", "rna.title": "Tipo celular a partir de tus datos de RNA-seq", "rna.howH": "Qué datos hacen falta (léelo primero)", "rna.how": "<p>Una tabla de texto (<b>.tsv</b>, <b>.csv</b> o <b>.txt</b>) con <b>una fila por gen</b>:</p><ul><li><b>Una columna de identificadores de gen.</b> Human-GEM: IDs de gen de Ensembl (<code>ENSG00000111640</code>; un sufijo de versión como <code>.15</code> no importa) o símbolos HGNC (<code>GAPDH</code>). Mouse-GEM / Rat-GEM: símbolos MGI / RGD (<code>Gapdh</code>). Zebrafish-GEM: símbolos ZFIN (<code>gapdh</code>); Fruitfly-GEM: símbolos FlyBase (<code>Gapdh1</code>); Worm-GEM: nombres de gen de WormBase (<code>gpd-1</code>). La columna se detecta sola.</li><li><b>Una o más columnas de expresión normalizada</b> en escala lineal: <b>TPM</b> (lo mejor), FPKM/RPKM, o CPM para célula única agrupada por tipo celular. <b>No lecturas crudas (counts)</b>: dependen de la longitud del gen y de la profundidad de secuenciación. Si tus valores son log2(x+1), marca la casilla y se convierten de vuelta.</li><li><b>A nivel de gen</b>, no de tránscrito: suma antes los tránscritos de cada gen.</li><li>Réplicas: elige una columna o la media de todas las columnas numéricas. Se admiten una fila de cabecera y líneas de comentario que empiecen por #.</li></ul><pre>gene_id\tTPM_rep1\tTPM_rep2\nENSG00000111640\t2410.5\t2388.1\nENSG00000134333\t396.7\t402.0\nENSG00000156515\t49.8\t51.2</pre><p><b>Qué ocurre.</b> Los genes por debajo del umbral (por defecto <b>1</b>, la convención del Human Protein Atlas para TPM) se apagan; los genes que no están en tu tabla siguen encendidos. Se bloquean las reacciones que se quedan sin enzima y se vuelven a encender genes hasta que las 57 tareas metabólicas esenciales de Human-GEM vuelven a ser posibles, exactamente igual que en el catálogo (Docs › Tipos celulares). Se ejecuta en tu navegador y tarda unos minutos (hasta unos siete en un ordenador cargado); mientras, puedes seguir trabajando. <b>Tus datos no salen de este ordenador</b>: el resultado se guarda en este navegador y dentro de las sesiones que exportes.</p><p><b>Elegir el umbral.</b> 1 TPM sirve para la mayoría del RNA-seq de población. Con secuenciación poco profunda o protocolos 3′ muchos genes reales quedan por debajo de 1: bájalo (0,5). Un umbral más alto apaga más genes y depende más del rescate por tareas.</p>", "rna.file": "Tabla de expresión:", "rna.idCol": "Identificadores de gen", "rna.valCol": "Valores de expresión", "rna.thr": "Umbral (por debajo se apagan)", "rna.name": "Nombre de este tipo celular", "rna.log": "Los valores son log2(x+1): convertirlos a escala lineal", "rna.column": "columna {n}", "rna.meanCols": "media de las {n} columnas numéricas", "rna.preview": "{rows} filas leídas, {used} emparejadas con {matched} de los {n} genes del modelo ({pct} %). Con el umbral {thr} se apagarían {off} genes antes del rescate por tareas.", "rna.lowMatch": "Se ha encontrado menos de la mitad de los genes del modelo: revisa la columna de identificadores y el modelo (IDs humanos para Human-GEM, símbolos de ratón para Mouse-GEM). Los genes que no están en la tabla siguen encendidos.", "rna.build": "Construir tipo celular", "rna.loading": "Arrancando el solver…", "rna.progress": "Comprobando la tarea metabólica {i} de {n}… ({s} s)", "rna.errEmpty": "El archivo no tiene filas de datos.", "rna.errNoValues": "No se ha encontrado ninguna columna de números aparte de los identificadores.", "rna.chipInfo": "De {file}: {matched} de {total} genes en la tabla, umbral {thr}.", "rna.delete": "borrar", "rna.deleteConfirm": "¿Borrar el tipo celular «{name}» de este navegador?", "rna.storageFull": "El almacenamiento del navegador está lleno: el tipo celular se usa ahora pero no se guarda."});
Object.assign(en, {"met.value": "Value for the objective: {x} per mmol/gDW/h supplied", "met.valueTitle": "Shadow price: how much the objective would rise if this metabolite were supplied for free in this compartment. 0 = it does not limit the objective now.", "sum.metValue": "Most valuable metabolites", "sum.metValueUnit": "objective gained per mmol/gDW/h supplied", "sum.metValueMore": "+{n} with the same value", "sum.metValueNote": "Shadow prices of the FBA solution: what the cell would gain from a free supply of each metabolite. Metabolites with the same value share one limitation; the smallest is shown.", "pp.button": "Vary its uptake (phase plane)", "pp.title": "The objective as the maximum uptake of this metabolite goes from 0 to about three times the current one", "pp.busy": "Computing the phase plane…", "pp.progress": "Phase plane: {i} of {n}…", "pp.head": "Phase plane", "pp.yAxis": "objective ({u})", "pp.xAxis": "maximum uptake of {n} (mmol/gDW/h)", "pp.now": "current uptake", "pp.note": "Each stretch is a regime in which the same bound limits the objective (shaded alternately; hover for its name). This metabolite's measured flux is left free, perturbations are left out, and FBA is used without pFBA.", "pp.infeasible": "no solution", "pp.none": "no single limit"});
