Object.assign(en, {"flex.cycles": "without cycles", "flex.cyclesTitle": "Cap the total flux at its pFBA minimum + 5 %, which removes internal loops (thermodynamically impossible cycles) that make ranges look wider than they are", "flex.noCycles": "Cycles excluded (total flux ≤ pFBA minimum + 5 %)."});
