Object.assign(en, {"tour.tabs.t": "The bottom bar", "tour.tabs.b": "Map shows the map alone. Setup opens the medium, cell type, objective and the rest of the inputs; Results the summary and the details of what you tap; More the mode, map options, tools, appearance and language. Pull a panel down to close it, up to enlarge it.", "tour.gestures.t": "Moving around the map", "tour.gestures.b": "One finger moves the map and two fingers zoom. Tap a node for its details, double-tap a group to open its pathway, and press and hold a node for a menu (centre the map on it, open its pathway, knock it out…).", "tour.more.t": "More", "tour.more.b": "Steady state or dynamic mode, map options, the methods, documentation, model editor, import and download, theme, colours, language and full screen.", "tour.again.t": "Run this walkthrough again", "tour.again.b": "This button starts the walkthrough again whenever you want.", "tour.cat.again.t": "Run this walkthrough again", "tour.cat.again.b": "This button starts the walkthrough again whenever you want."});
Object.assign(es, {"tour.tabs.t": "La barra inferior", "tour.tabs.b": "Mapa muestra sólo el mapa. Ajustes abre el medio, el tipo celular, el objetivo y el resto de entradas; Resultados, el resumen y los detalles de lo que toques; Más, el modo, las opciones del mapa, herramientas, apariencia e idioma. Desliza un panel hacia abajo para cerrarlo y hacia arriba para ampliarlo.", "tour.gestures.t": "Moverse por el mapa", "tour.gestures.b": "Un dedo mueve el mapa y dos dedos hacen zoom. Toca un nodo para ver sus detalles, toca dos veces un grupo para abrir su ruta y mantén pulsado un nodo para abrir un menú (centrar el mapa en él, abrir su ruta, anularlo…).", "tour.more.t": "Más", "tour.more.b": "Modo estacionario o dinámico, opciones del mapa, métodos, documentación, editor del modelo, importar y descargar, tema, colores, idioma y pantalla completa.", "tour.again.t": "Repetir este recorrido", "tour.again.b": "Este botón vuelve a iniciar el recorrido cuando quieras.", "tour.cat.again.t": "Repetir este recorrido", "tour.cat.again.b": "Este botón vuelve a iniciar el recorrido cuando quieras."});
Object.assign(en, {"medium.name.schneider": "Schneider's (Drosophila S2 cells)", "medium.note.schneider": "Schneider's Drosophila Medium as sold by Gibco (21720), the medium of Drosophila S2 cells, at the manufacturer's concentrations: 11 mM glucose, 5.8 mM trehalose, 12 mM glutamine, high amino acids, β-alanine and four TCA-cycle acids. Its yeastolate and the 10 % FBS used with S2 cells are what supply vitamins, nucleobases and lipids; they are taken from the standard medium."});
Object.assign(es, {"medium.name.schneider": "Schneider (células S2 de Drosophila)", "medium.note.schneider": "Medio de Schneider para Drosophila tal como lo vende Gibco (21720), el medio de las células S2 de Drosophila, a las concentraciones del fabricante: 11 mM de glucosa, 5,8 mM de trehalosa, 12 mM de glutamina, aminoácidos altos, β-alanina y cuatro ácidos del ciclo de Krebs. Su extracto de levadura y el 10 % de FBS que se usa con las S2 son los que aportan vitaminas, bases nitrogenadas y lípidos; se toman del medio estándar."});
Object.assign(en, {"obj.group.kidney": "Kidney", "obj.group.muscle": "Muscle and heart", "obj.group.immune": "Blood, bone marrow and immune cells", "obj.name.ammonia": "Ammonia excretion (kidney, ammoniagenesis)", "obj.note.ammonia": "Maximises NH4+ release (MAR11420). The proximal tubule makes ammonium from glutamine to excrete acid, above all in acidosis. About 0.55 mmol/gDW/h in the standard medium.", "obj.name.gaa": "Guanidinoacetate release (kidney, creatine synthesis step 1)", "obj.note.gaa": "Maximises guanidinoacetate release (MAR09852), made by arginine:glycine amidinotransferase (AGAT) in the kidney and methylated to creatine in the liver. About 0.20 mmol/gDW/h.", "obj.name.arginine": "Arginine synthesis (kidney)", "obj.note.arginine": "Maximises arginine release (MAR09066) with arginine uptake closed. The proximal tubule makes most of the body's arginine from citrulline (argininosuccinate synthetase and lyase). About 0.13 mmol/gDW/h.", "obj.name.glnRelease": "Glutamine release (skeletal muscle)", "obj.note.glnRelease": "Maximises glutamine release (MAR09063) with its uptake closed. Skeletal muscle is the main source of plasma glutamine, made from branched-chain amino acid nitrogen. About 0.18 mmol/gDW/h.", "obj.name.alaRelease": "Alanine release (skeletal muscle, glucose–alanine cycle)", "obj.note.alaRelease": "Maximises alanine release (MAR09061): muscle transaminates pyruvate to alanine, which the liver turns back into glucose (glucose–alanine cycle). About 0.54 mmol/gDW/h.", "obj.name.oxATP": "Oxidative ATP (cardiomyocyte, ATP synthase)", "obj.note.oxATP": "Maximises mitochondrial ATP synthase (MAR06916). The heart makes more than 95 % of its ATP by oxidative phosphorylation, mostly from fatty acids; add or raise fatty acids in the medium to see that. About 17 mmol/gDW/h, limited by oxygen.", "obj.name.txa2": "Thromboxane A2 (platelets)", "obj.note.txa2": "Maximises thromboxane A2 release (MAR09433), made by platelets from arachidonate (COX-1, thromboxane synthase). Limited by the essential fatty acids of the medium (about 0.006 mmol/gDW/h).", "obj.name.itaconate": "Itaconate (activated macrophage)", "obj.note.itaconate": "Maximises itaconate release (MAR09451), made from cis-aconitate by ACOD1 (IRG1) in macrophages activated by LPS; it inhibits succinate dehydrogenase. About 0.93 mmol/gDW/h. Flies and worms have no ACOD1: 0.", "obj.name.pge2": "Prostaglandin E2 (macrophage)", "obj.note.pge2": "Maximises prostaglandin E2 release (MAR09397), made by macrophages through COX-2 during inflammation. Limited by the essential fatty acids of the medium.", "obj.name.ltb4": "Leukotriene B4 (neutrophil)", "obj.note.ltb4": "Maximises leukotriene B4 release (MAR09365), the neutrophil chemoattractant made by 5-lipoxygenase from arachidonate. Limited by the essential fatty acids of the medium.", "obj.name.histamine": "Histamine (mast cell, basophil)", "obj.note.histamine": "Maximises histamine release (MAR00619), made by histidine decarboxylase in mast cells and basophils. Limited by histidine uptake.", "obj.name.spermidine": "Spermidine (activated T lymphocyte)", "obj.note.spermidine": "Maximises spermidine release (MAR11427). Activated T lymphocytes switch on polyamine synthesis (ornithine decarboxylase) to proliferate. About 0.18 mmol/gDW/h."});
Object.assign(es, {"obj.group.kidney": "Riñón", "obj.group.muscle": "Músculo y corazón", "obj.group.immune": "Sangre, médula ósea y células inmunitarias", "obj.name.ammonia": "Excreción de amonio (riñón, amoniogénesis)", "obj.note.ammonia": "Maximiza la liberación de NH4+ (MAR11420). El túbulo proximal fabrica amonio a partir de glutamina para excretar ácido, sobre todo en acidosis. Unos 0,55 mmol/gDW/h en el medio estándar.", "obj.name.gaa": "Liberación de guanidinoacetato (riñón, primer paso de la creatina)", "obj.note.gaa": "Maximiza la liberación de guanidinoacetato (MAR09852), que fabrica la arginina:glicina amidinotransferasa (AGAT) en el riñón y que el hígado metila a creatina. Unos 0,20 mmol/gDW/h.", "obj.name.arginine": "Síntesis de arginina (riñón)", "obj.note.arginine": "Maximiza la liberación de arginina (MAR09066) con su captación cerrada. El túbulo proximal fabrica la mayor parte de la arginina del cuerpo a partir de citrulina (argininosuccinato sintetasa y liasa). Unos 0,13 mmol/gDW/h.", "obj.name.glnRelease": "Liberación de glutamina (músculo esquelético)", "obj.note.glnRelease": "Maximiza la liberación de glutamina (MAR09063) con su captación cerrada. El músculo esquelético es la principal fuente de glutamina del plasma, hecha con el nitrógeno de los aminoácidos ramificados. Unos 0,18 mmol/gDW/h.", "obj.name.alaRelease": "Liberación de alanina (músculo esquelético, ciclo glucosa–alanina)", "obj.note.alaRelease": "Maximiza la liberación de alanina (MAR09061): el músculo transamina piruvato a alanina, que el hígado vuelve a convertir en glucosa (ciclo glucosa–alanina). Unos 0,54 mmol/gDW/h.", "obj.name.oxATP": "ATP oxidativo (cardiomiocito, ATP sintasa)", "obj.note.oxATP": "Maximiza la ATP sintasa mitocondrial (MAR06916). El corazón obtiene más del 95 % de su ATP por fosforilación oxidativa, sobre todo de ácidos grasos; añade o sube ácidos grasos en el medio para verlo. Unos 17 mmol/gDW/h, limitado por el oxígeno.", "obj.name.txa2": "Tromboxano A2 (plaquetas)", "obj.note.txa2": "Maximiza la liberación de tromboxano A2 (MAR09433), que las plaquetas fabrican a partir de araquidonato (COX-1, tromboxano sintasa). Limitado por los ácidos grasos esenciales del medio (unos 0,006 mmol/gDW/h).", "obj.name.itaconate": "Itaconato (macrófago activado)", "obj.note.itaconate": "Maximiza la liberación de itaconato (MAR09451), que ACOD1 (IRG1) fabrica a partir de cis-aconitato en macrófagos activados por LPS; inhibe la succinato deshidrogenasa. Unos 0,93 mmol/gDW/h. Moscas y gusanos no tienen ACOD1: 0.", "obj.name.pge2": "Prostaglandina E2 (macrófago)", "obj.note.pge2": "Maximiza la liberación de prostaglandina E2 (MAR09397), que los macrófagos fabrican por la COX-2 durante la inflamación. Limitado por los ácidos grasos esenciales del medio.", "obj.name.ltb4": "Leucotrieno B4 (neutrófilo)", "obj.note.ltb4": "Maximiza la liberación de leucotrieno B4 (MAR09365), el quimioatrayente de neutrófilos que fabrica la 5-lipoxigenasa a partir de araquidonato. Limitado por los ácidos grasos esenciales del medio.", "obj.name.histamine": "Histamina (mastocito, basófilo)", "obj.note.histamine": "Maximiza la liberación de histamina (MAR00619), que fabrica la histidina descarboxilasa en mastocitos y basófilos. Limitado por la captación de histidina.", "obj.name.spermidine": "Espermidina (linfocito T activado)", "obj.note.spermidine": "Maximiza la liberación de espermidina (MAR11427). Los linfocitos T activados encienden la síntesis de poliaminas (ornitina descarboxilasa) para proliferar. Unos 0,18 mmol/gDW/h."});
Object.assign(en, {"sec.title": "Secondary objective", "sec.pickTitle": "Optimised after the objective, without letting it fall below the fraction chosen", "sec.keep": "Keep the objective at", "sec.hint": "First the objective is optimised; then the secondary is made as large as possible while the objective keeps at least this share of its optimum. Not a weighted sum: the two have different units, and a weighted sum jumps from one extreme to the other. <a href=\"docs.html#en-secondary\" target=\"_blank\">More</a>", "sec.curve": "Trade-off curve", "sec.curveTitle": "The best secondary at each share of the objective's optimum, from 100 % to 0 % (Pareto front)", "sec.none": "None", "sec.noCurve": "No solution at any point of the curve.", "sec.curveHead": "Trade-off curve", "sec.steep": "Steepest stretch: from {a} % to {b} % of the objective, each unit of it given up buys {r} of the secondary.", "sec.curveNote": "Each point: the best secondary when the objective keeps that share of its optimum (FBA, perturbations left out). The orange point is the share in use.", "sum.secondary": "Secondary objective", "sum.secKeep": "objective kept ≥ {p} %"});
Object.assign(es, {"sec.title": "Objetivo secundario", "sec.pickTitle": "Se optimiza después del objetivo, sin dejar que este baje de la fracción elegida", "sec.keep": "Mantener el objetivo al", "sec.hint": "Primero se optimiza el objetivo; después el secundario se hace lo mayor posible mientras el objetivo conserva al menos esta parte de su óptimo. No es una suma ponderada: los dos tienen unidades distintas y una suma ponderada salta de un extremo a otro. <a href=\"docs.html#es-secondary\" target=\"_blank\">Más</a>", "sec.curve": "Curva de compromiso", "sec.curveTitle": "El mejor secundario para cada parte del óptimo del objetivo, de 100 % a 0 % (frente de Pareto)", "sec.none": "Ninguno", "sec.noCurve": "No hay solución en ningún punto de la curva.", "sec.curveHead": "Curva de compromiso", "sec.steep": "Tramo más empinado: de {a} % a {b} % del objetivo, cada unidad a la que se renuncia da {r} del secundario.", "sec.curveNote": "Cada punto: el mejor secundario cuando el objetivo conserva esa parte de su óptimo (FBA, sin perturbaciones). El punto naranja es la parte en uso.", "sum.secondary": "Objetivo secundario", "sum.secKeep": "objetivo mantenido ≥ {p} %"});
Object.assign(en, {"sec.progress": "Trade-off curve: point {i} of {n}…"});
Object.assign(es, {"sec.progress": "Curva de compromiso: punto {i} de {n}…"});
Object.assign(en, {"obj.group.microbe": "Fermentation and bioproduction", "obj.name.atpMicro": "Maximum ATP (maintenance reaction)", "obj.note.atpMicro": "Maximises the model's ATP maintenance reaction (ATPM in iML1515, r_4046 in yeast-GEM; its upper bound is opened while it is the objective): the most ATP the cell can make from what it takes up. With O2 it comes from respiration; without it, from fermentation (2 ATP per glucose in yeast).", "obj.name.ethanol": "Ethanol", "obj.note.ethanol": "Maximises ethanol release: 2 per glucose at most (yeast pyruvate decarboxylase and alcohol dehydrogenase; in E. coli, AdhE in mixed-acid fermentation).", "obj.name.glycerol": "Glycerol", "obj.note.glycerol": "Maximises glycerol release (Gpd1/2 and Gpp1/2): the redox sink of anaerobic yeast and its response to osmotic stress.", "obj.name.acetate": "Acetate", "obj.note.acetate": "Maximises acetate release: E. coli's overflow product when respiration saturates (Pta–AckA, PoxB); in yeast, the aldehyde dehydrogenase branch.", "obj.name.succinate": "Succinate", "obj.note.succinate": "Maximises succinate release: in E. coli the reductive branch of the TCA cycle (fumarate reductase), the basis of bio-based succinate production; most of it without O2.", "obj.name.dlactate": "D-lactate", "obj.note.dlactate": "Maximises D-lactate release by LdhA, a mixed-acid fermentation product of E. coli and a target for bioplastics (PLA).", "obj.name.formate": "Formate", "obj.note.formate": "Maximises formate release from pyruvate formate-lyase, the main C1 product of anaerobic E. coli.", "obj.name.butanediol": "2,3-Butanediol", "obj.note.butanediol": "Maximises (R,R)-2,3-butanediol release from acetoin (Bdh1), a platform chemical and a minor product of yeast fermentation.", "obj.name.isobutanol": "Isobutanol", "obj.note.isobutanol": "Maximises isobutanol release through the valine pathway and the Ehrlich pathway, an advanced biofuel made by engineered yeast.", "obj.name.phenylethanol": "2-Phenylethanol", "obj.note.phenylethanol": "Maximises 2-phenylethanol release (rose aroma) from phenylalanine through the Ehrlich pathway.", "obj.name.isoamylol": "Isoamyl alcohol", "obj.note.isoamylol": "Maximises isoamyl alcohol release from leucine biosynthesis and the Ehrlich pathway: a fusel alcohol that shapes the aroma of beer and wine.", "obj.name.lysineProd": "Lysine production", "obj.note.lysineProd": "Maximises L-lysine release through the diaminopimelate pathway: an amino acid made industrially by bacteria (here the theoretical yield of E. coli).", "medium.name.m9glc": "M9 glucose (E. coli)", "medium.note.m9glc": "M9 minimal salts (Sambrook & Russell 2001) with 0.4 % glucose (22 mM), aerobic. Oxygen capacity 15 mmol/gDW/h (Varma & Palsson 1994), with which FBA reproduces acetate overflow.", "medium.name.m9glcAnaer": "M9 glucose, anaerobic (E. coli)", "medium.note.m9glcAnaer": "As M9 glucose, without oxygen: mixed-acid fermentation (acetate, ethanol, formate, succinate, lactate).", "medium.name.m9glyc": "M9 glycerol (E. coli)", "medium.note.m9glyc": "M9 minimal salts with 0.4 % glycerol (43 mM), aerobic.", "medium.name.m9ace": "M9 acetate (E. coli)", "medium.note.m9ace": "M9 minimal salts with 0.4 % acetate (49 mM), aerobic: gluconeogenic growth through the glyoxylate shunt.", "medium.name.m9succ": "M9 succinate (E. coli)", "medium.note.m9succ": "M9 minimal salts with 0.4 % succinate (34 mM), aerobic.", "medium.name.verduyn": "Verduyn mineral medium (yeast)", "medium.note.verduyn": "The defined mineral medium of Verduyn et al. 1992 with its vitamins and 20 g/L glucose, aerobic. Oxygen capacity 8 mmol/gDW/h: above it the excess glucose is fermented to ethanol (Crabtree effect).", "medium.name.verduynAnaer": "Verduyn anaerobic (yeast)", "medium.note.verduynAnaer": "Verduyn medium without oxygen, with ergosterol and Tween 80 (oleate), which yeast cannot make without O2; palmitoleate and a trace of heme a are let in as in yeast-GEM's anaerobic setting.", "medium.name.ynb": "YNB glucose (yeast)", "medium.note.ynb": "Difco Yeast Nitrogen Base without amino acids (ammonium sulfate, vitamins, salts) with 2 % glucose, aerobic.", "medium.name.sc": "Synthetic complete, SC (yeast)", "medium.note.sc": "YNB with 2 % glucose and the Complete Supplement Mixture (CSM): amino acids, adenine and uracil, needed by auxotrophic laboratory strains.", "meas.name.yeastO2_209": "Yeast chemostat, 20.9 % O2 (Jouhten 2008)", "meas.note.yeastO2_209": "S. cerevisiae CEN.PK113-1A, glucose-limited chemostat at D = 0.10 1/h, air: fully respiratory, no ethanol.", "meas.name.yeastO2_28": "Yeast chemostat, 2.8 % O2 (Jouhten 2008)", "meas.note.yeastO2_28": "As above with 2.8 % O2 in the inlet gas: still respiratory, a trace of ethanol.", "meas.name.yeastO2_10": "Yeast chemostat, 1.0 % O2 (Jouhten 2008)", "meas.note.yeastO2_10": "1.0 % O2: respiro-fermentative, glucose uptake almost doubles and ethanol appears.", "meas.name.yeastO2_05": "Yeast chemostat, 0.5 % O2 (Jouhten 2008)", "meas.note.yeastO2_05": "0.5 % O2: mostly fermentative.", "meas.name.yeastO2_0": "Yeast chemostat, anaerobic (Jouhten 2008)", "meas.note.yeastO2_0": "No O2: fully fermentative, ethanol and glycerol; loads the anaerobic Verduyn medium.", "meas.name.ecoliZampieri": "E. coli BW25113, M9 glucose (Zampieri 2019)", "meas.note.ecoliZampieri": "Aerobic batch on M9 glucose: growth 0.70 1/h, glucose uptake and acetate overflow (mean ± SD).", "meas.name.ecoliGlcAer": "E. coli BW25113, glucose aerobic (Castaño-Cerezo 2009)", "meas.note.ecoliGlcAer": "Aerobic batch on glucose minimal medium: growth 0.74 1/h; acetate, ethanol, formate and D-lactate release.", "meas.name.ecoliGlcAnaer": "E. coli BW25113, glucose anaerobic (Castaño-Cerezo 2009)", "meas.note.ecoliGlcAnaer": "Anaerobic batch on glucose: mixed-acid fermentation, growth 0.48 1/h; loads the anaerobic M9 medium."});
Object.assign(en, {"meas.name.yeastSD": "Yeast batch, SD glucose (Fujiwara 2025)", "meas.note.yeastSD": "S. cerevisiae BY4947 (S288C background), aerobic batch in SD medium (glucose, yeast nitrogen base): growth 0.37 1/h, glucose uptake and secretion of ethanol, glycerol and acetate (mean ± SD). Despite the oxygen, most glucose is fermented (Crabtree effect)."});
Object.assign(es, {"obj.group.microbe": "Fermentación y bioproducción", "obj.name.atpMicro": "ATP máximo (reacción de mantenimiento)", "obj.note.atpMicro": "Maximiza la reacción de mantenimiento de ATP del modelo (ATPM en iML1515, r_4046 en yeast-GEM; su límite superior se abre mientras es el objetivo): el máximo ATP que la célula puede obtener de lo que capta. Con O2 viene de la respiración; sin él, de la fermentación (2 ATP por glucosa en levadura).", "obj.name.ethanol": "Etanol", "obj.note.ethanol": "Maximiza la liberación de etanol: como mucho 2 por glucosa (piruvato descarboxilasa y alcohol deshidrogenasa en levadura; en E. coli, AdhE en la fermentación ácido-mixta).", "obj.name.glycerol": "Glicerol", "obj.note.glycerol": "Maximiza la liberación de glicerol (Gpd1/2 y Gpp1/2): el sumidero redox de la levadura anaerobia y su respuesta al estrés osmótico.", "obj.name.acetate": "Acetato", "obj.note.acetate": "Maximiza la liberación de acetato: el producto de desbordamiento de E. coli cuando la respiración se satura (Pta–AckA, PoxB); en levadura, la rama de la aldehído deshidrogenasa.", "obj.name.succinate": "Succinato", "obj.note.succinate": "Maximiza la liberación de succinato: en E. coli la rama reductora del ciclo de Krebs (fumarato reductasa), base de la producción biológica de succinato; sobre todo sin O2.", "obj.name.dlactate": "D-lactato", "obj.note.dlactate": "Maximiza la liberación de D-lactato por LdhA, un producto de la fermentación ácido-mixta de E. coli y objetivo para bioplásticos (PLA).", "obj.name.formate": "Formiato", "obj.note.formate": "Maximiza la liberación de formiato de la piruvato formiato-liasa, el principal producto C1 de E. coli anaerobia.", "obj.name.butanediol": "2,3-Butanodiol", "obj.note.butanediol": "Maximiza la liberación de (R,R)-2,3-butanodiol a partir de acetoína (Bdh1), un compuesto plataforma y producto menor de la fermentación de levadura.", "obj.name.isobutanol": "Isobutanol", "obj.note.isobutanol": "Maximiza la liberación de isobutanol por la ruta de la valina y la vía de Ehrlich, un biocombustible avanzado de levaduras modificadas.", "obj.name.phenylethanol": "2-Feniletanol", "obj.note.phenylethanol": "Maximiza la liberación de 2-feniletanol (aroma a rosa) a partir de fenilalanina por la vía de Ehrlich.", "obj.name.isoamylol": "Alcohol isoamílico", "obj.note.isoamylol": "Maximiza la liberación de alcohol isoamílico desde la síntesis de leucina y la vía de Ehrlich: un alcohol de fusel que da aroma a la cerveza y el vino.", "obj.name.lysineProd": "Producción de lisina", "obj.note.lysineProd": "Maximiza la liberación de L-lisina por la ruta del diaminopimelato: un aminoácido que se produce industrialmente con bacterias (aquí el rendimiento teórico de E. coli).", "medium.name.m9glc": "M9 glucosa (E. coli)", "medium.note.m9glc": "Sales mínimas M9 (Sambrook y Russell 2001) con 0,4 % de glucosa (22 mM), aerobio. Capacidad de oxígeno 15 mmol/gDW/h (Varma y Palsson 1994), con la que el FBA reproduce el desbordamiento de acetato.", "medium.name.m9glcAnaer": "M9 glucosa, anaerobio (E. coli)", "medium.note.m9glcAnaer": "Como M9 glucosa, sin oxígeno: fermentación ácido-mixta (acetato, etanol, formiato, succinato, lactato).", "medium.name.m9glyc": "M9 glicerol (E. coli)", "medium.note.m9glyc": "Sales mínimas M9 con 0,4 % de glicerol (43 mM), aerobio.", "medium.name.m9ace": "M9 acetato (E. coli)", "medium.note.m9ace": "Sales mínimas M9 con 0,4 % de acetato (49 mM), aerobio: crecimiento gluconeogénico por el ciclo del glioxilato.", "medium.name.m9succ": "M9 succinato (E. coli)", "medium.note.m9succ": "Sales mínimas M9 con 0,4 % de succinato (34 mM), aerobio.", "medium.name.verduyn": "Medio mineral de Verduyn (levadura)", "medium.note.verduyn": "El medio mineral definido de Verduyn et al. 1992 con sus vitaminas y 20 g/L de glucosa, aerobio. Capacidad de oxígeno 8 mmol/gDW/h: por encima, la glucosa sobrante se fermenta a etanol (efecto Crabtree).", "medium.name.verduynAnaer": "Verduyn anaerobio (levadura)", "medium.note.verduynAnaer": "Medio de Verduyn sin oxígeno, con ergosterol y Tween 80 (oleato), que la levadura no puede fabricar sin O2; entran también palmitoleato y trazas de hemo a, como en la configuración anaerobia de yeast-GEM.", "medium.name.ynb": "YNB glucosa (levadura)", "medium.note.ynb": "Yeast Nitrogen Base de Difco sin aminoácidos (sulfato amónico, vitaminas, sales) con 2 % de glucosa, aerobio.", "medium.name.sc": "Sintético completo, SC (levadura)", "medium.note.sc": "YNB con 2 % de glucosa y la mezcla de suplementos completa (CSM): aminoácidos, adenina y uracilo, que necesitan las cepas auxótrofas de laboratorio.", "meas.name.yeastO2_209": "Levadura en quimiostato, 20,9 % O2 (Jouhten 2008)", "meas.note.yeastO2_209": "S. cerevisiae CEN.PK113-1A, quimiostato limitado por glucosa a D = 0,10 1/h, aire: totalmente respiratoria, sin etanol.", "meas.name.yeastO2_28": "Levadura en quimiostato, 2,8 % O2 (Jouhten 2008)", "meas.note.yeastO2_28": "Igual con 2,8 % de O2 en el gas de entrada: aún respiratoria, trazas de etanol.", "meas.name.yeastO2_10": "Levadura en quimiostato, 1,0 % O2 (Jouhten 2008)", "meas.note.yeastO2_10": "1,0 % de O2: respiro-fermentativa, la captación de glucosa casi se duplica y aparece etanol.", "meas.name.yeastO2_05": "Levadura en quimiostato, 0,5 % O2 (Jouhten 2008)", "meas.note.yeastO2_05": "0,5 % de O2: mayoritariamente fermentativa.", "meas.name.yeastO2_0": "Levadura en quimiostato, anaerobia (Jouhten 2008)", "meas.note.yeastO2_0": "Sin O2: totalmente fermentativa, etanol y glicerol; carga el medio de Verduyn anaerobio.", "meas.name.ecoliZampieri": "E. coli BW25113, M9 glucosa (Zampieri 2019)", "meas.note.ecoliZampieri": "Cultivo discontinuo aerobio en M9 glucosa: crecimiento 0,70 1/h, captación de glucosa y desbordamiento de acetato (media ± DE).", "meas.name.ecoliGlcAer": "E. coli BW25113, glucosa aerobia (Castaño-Cerezo 2009)", "meas.note.ecoliGlcAer": "Cultivo discontinuo aerobio en medio mínimo con glucosa: crecimiento 0,74 1/h; liberación de acetato, etanol, formiato y D-lactato.", "meas.name.ecoliGlcAnaer": "E. coli BW25113, glucosa anaerobia (Castaño-Cerezo 2009)", "meas.note.ecoliGlcAnaer": "Cultivo discontinuo anaerobio en glucosa: fermentación ácido-mixta, crecimiento 0,48 1/h; carga el medio M9 anaerobio."});
Object.assign(es, {"meas.name.yeastSD": "Levadura en discontinuo, SD con glucosa (Fujiwara 2025)", "meas.note.yeastSD": "S. cerevisiae BY4947 (fondo S288C), cultivo discontinuo aerobio en medio SD (glucosa, base nitrogenada de levadura): crecimiento 0,37 1/h, captación de glucosa y secreción de etanol, glicerol y acetato (media ± DE). Pese al oxígeno, la mayor parte de la glucosa se fermenta (efecto Crabtree)."});
Object.assign(en, {"ctx.group.strain": "Strain", "ctx.badge.strain": "Strain", "ctx.src.genotype": "published genotype", "ctx.license.genotype": "Genotype from the literature: the deleted metabolic genes are switched off. <a href=\"docs.html?lang={lang}#{lang}-strains\" target=\"_blank\" rel=\"noopener\">Strains and their sources</a>."});
Object.assign(es, {"ctx.group.strain": "Cepa", "ctx.badge.strain": "Cepa", "ctx.src.genotype": "genotipo publicado", "ctx.license.genotype": "Genotipo de la bibliografía: se apagan los genes metabólicos delecionados. <a href=\"docs.html?lang={lang}#{lang}-strains\" target=\"_blank\" rel=\"noopener\">Cepas y sus fuentes</a>."});
