Object.assign(es, {"comp.peri": "Periplasma", "comp.wall": "Envoltura celular", "comp.vac": "Vacuola", "comp.lipid": "Partícula lipídica", "loc.outer": "Membrana externa", "loc.wall": "Pared celular"});
Object.assign(en, {"obj.name.protein": "Protein secretion (plasma cell)", "obj.note.protein": "Maximises a demand of the cell's protein pool (MFL_DM_protein, added by MetfluxLive and open only while it is the objective): plasma cells no longer divide and spend their metabolism on secreting antibodies. The pool has the average amino acid composition of a cell, not that of an immunoglobulin. About 0.25 mmol pool/gDW/h (5 % of the cell's protein per hour), limited by amino acids. For activated, proliferating T or B cells use growth, with spermidine or lactate as secondary objective."});
Object.assign(es, {"obj.name.protein": "Secreción de proteína (célula plasmática)", "obj.note.protein": "Maximiza una demanda de la reserva de proteína de la célula (MFL_DM_protein, añadida por MetfluxLive y abierta sólo mientras es el objetivo): las células plasmáticas ya no se dividen y dedican su metabolismo a secretar anticuerpos. La reserva tiene la composición media de aminoácidos de una célula, no la de una inmunoglobulina. Unos 0,25 mmol de reserva/gDW/h (5 % de la proteína celular por hora), limitado por los aminoácidos. Para linfocitos T o B activados que proliferan usa el crecimiento, con espermidina o lactato como objetivo secundario."});
export const DICT = { es, en, pt, it, fr, de, el };
export const LANGS = [["en", "English"], ["es", "Español"], ["pt", "Português"], ["it", "Italiano"], ["fr", "Français"], ["de", "Deutsch"], ["el", "Ελληνικά"]];
// languages the documentation (docs.html + docs/<code>.html) is written in; any other opens it in English
export const DOCS_LANGS = ["en", "es", "pt", "it", "fr", "de", "el"];
let lang = "en";

export const getLang = () => lang;
export const docsLang = () => (DOCS_LANGS.includes(lang) ? lang : "en");

export function setLang(l) {
  lang = DICT[l] ? l : "en";
  try { localStorage.setItem("metflux.lang", lang); } catch { /* storage unavailable */ }
  if (typeof document !== "undefined") document.documentElement.lang = lang;
}

export function initLang() {
  let l = "en";
  try { l = localStorage.getItem("metflux.lang") || l; } catch { /* storage unavailable */ }
  lang = DICT[l] ? l : "en";
  document.documentElement.lang = lang;
}

export function t(key, vars) {
  let s = DICT[lang][key] ?? en[key] ?? key;
  if (vars) s = s.replace(/\{(\w+)\}/g, (m, k) => (k in vars ? vars[k] : m));
  return s;
}

/** Fill every element carrying a data-i18n* attribute. */
export function applyDom(root = document) {
  root.querySelectorAll("[data-i18n]").forEach((el) => { el.textContent = t(el.dataset.i18n); });
  root.querySelectorAll("[data-i18n-html]").forEach((el) => { el.innerHTML = t(el.dataset.i18nHtml); });
  root.querySelectorAll("[data-i18n-title]").forEach((el) => { el.title = t(el.dataset.i18nTitle); });
  root.querySelectorAll("[data-i18n-label]").forEach((el) => { el.label = t(el.dataset.i18nLabel); });
  root.querySelectorAll("[data-i18n-ph]").forEach((el) => { el.placeholder = t(el.dataset.i18nPh); });
  root.querySelectorAll("[data-i18n-aria]").forEach((el) => { el.setAttribute("aria-label", t(el.dataset.i18nAria)); });
}
